#include <bits/stdc++.h>
using namespace std;

static const long long MOD = 998244353;

long long modPow(long long a, long long e) {
    long long result = 1;
    while (e > 0) {
        if (e & 1) result = result * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int p, s, r;
    cin >> p >> s >> r;

    int limit = s + p + 5;
    vector<long long> fact(limit), invFact(limit);

    fact[0] = 1;
    for (int i = 1; i < limit; ++i)
        fact[i] = fact[i - 1] * i % MOD;

    invFact[limit - 1] = modPow(fact[limit - 1], MOD - 2);
    for (int i = limit - 1; i > 0; --i)
        invFact[i - 1] = invFact[i] * i % MOD;

    auto C = [&](int n, int k) -> long long {
        if (n < 0 || k < 0 || k > n) return 0;
        return fact[n] * invFact[k] % MOD * invFact[n - k] % MOD;
    };

    if (s == 0) {
        cout << modPow(p, MOD - 2) << '\n';
        return 0;
    }

    int opponents = p - 1;
    long long numerator = 0;

    for (int x = max(r, 1); x <= s; ++x) {
        int remaining = s - x;
        int maxEqual = min(opponents, remaining / x);

        for (int equal = 0; equal <= maxEqual; ++equal) {
            int others = opponents - equal;
            int sumOthers = remaining - equal * x;

            long long ways = 0;

            if (others == 0) {
                ways = (sumOthers == 0);
            } else if (sumOthers <= 1LL * others * (x - 1)) {
                int maxExcluded = min(others, sumOthers / x);

                for (int j = 0; j <= maxExcluded; ++j) {
                    int value = sumOthers - j * x;
                    long long term = C(others, j) *
                                     C(value + others - 1, others - 1) % MOD;

                    if (j & 1) {
                        ways -= term;
                        if (ways < 0) ways += MOD;
                    } else {
                        ways += term;
                        if (ways >= MOD) ways -= MOD;
                    }
                }
            }

            long long chooseEqual = C(opponents, equal);
            long long tieProbability = modPow(equal + 1, MOD - 2);

            numerator = (numerator +
                         chooseEqual * ways % MOD * tieProbability) % MOD;
        }
    }

    long long totalStates = C(s - r + p - 1, p - 1);
    long long answer = numerator * modPow(totalStates, MOD - 2) % MOD;

    cout << answer << '\n';
    return 0;
}

