    int p, s, r;
    cin >> p >> s >> r;

    if (s == 0) {
        cout << modPow(p, MOD - 2) << '\n';
        return 0;
    }

    int maxN = s + p + 5;
    vector<long long> fact(maxN), invFact(maxN), inv(p + 1);

    fact[0] = 1;
    for (int i = 1; i < maxN; ++i)
        fact[i] = fact[i - 1] * i % MOD;

    invFact[maxN - 1] = modPow(fact[maxN - 1], MOD - 2);
    for (int i = maxN - 1; i > 0; --i)
        invFact[i - 1] = invFact[i] * i % MOD;

    auto C = [&](int n, int k) -> long long {
        if (k < 0 || k > n || n < 0) return 0;
        return fact[n] * invFact[k] % MOD * invFact[n - k] % MOD;
    };

    for (int i = 1; i <= p; ++i)
        inv[i] = modPow(i, MOD - 2);

    long long weightedWins = 0;

    for (int x = max(r, 1); x <= s; ++x) {
        for (int tied = 1; tied <= p; ++tied) {
            int remainingSum = s - tied * x;
            if (remainingSum < 0) break;

            int remainingPlayers = p - tied;
            long long ways = 0;

            if (remainingPlayers == 0) {
                ways = (remainingSum == 0);
            } else {
                int maxExcluded = min(remainingPlayers, remainingSum / x);
                for (int j = 0; j <= maxExcluded; ++j) {
                    long long term =
                        C(remainingPlayers, j) *
                        C(remainingSum - j * x + remainingPlayers - 1,
                          remainingPlayers - 1) % MOD;

                    if (j & 1) {
                        ways -= term;
                        if (ways < 0) ways += MOD;
                    } else {
                        ways += term;
                        if (ways >= MOD) ways -= MOD;
                    }
                }
            }

            long long chooseTied = C(p - 1, tied - 1);
            long long contribution = chooseTied * ways % MOD * inv[tied] % MOD;
            weightedWins += contribution;
            if (weightedWins >= MOD) weightedWins -= MOD;
        }
    }

    long long totalStates = C(s - r + p - 1, p - 1);
    long long answer = weightedWins * modPow(totalStates, MOD - 2) % MOD;

    cout << answer << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

const int64 MOD = 998244353;

int64 modPow(int64 a, int64 e) {
    int64 result = 1;
    while (e > 0) {
        if (e & 1) result = result * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return result;
