int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int p, s, r;
    cin >> p >> s >> r;

    int limit = s + p + 5;
    vector<int64> fact(limit), invFact(limit);
    fact[0] = 1;
    for (int i = 1; i < limit; ++i) {
        fact[i] = fact[i - 1] * i % MOD;
    }

    invFact[limit - 1] = modPow(fact[limit - 1], MOD - 2);
    for (int i = limit - 1; i > 0; --i) {
        invFact[i - 1] = invFact[i] * i % MOD;
    }

    auto C = [&](int n, int k) -> int64 {
        if (n < 0 || k < 0 || k > n) return 0;
        return fact[n] * invFact[k] % MOD * invFact[n - k] % MOD;
    };

    int64 totalStates = C(s + p - 1, p - 1);
    int64 maxAtLeastR;

    if (r == 0) {
        maxAtLeastR = totalStates;
    } else {
        int64 boundedStates = 0;
        int maxJ = min(p, s / r);

        for (int j = 0; j <= maxJ; ++j) {
            int remaining = s - j * r;
            int64 term = C(p, j) * C(remaining + p - 1, p - 1) % MOD;

            if (j & 1) {
                boundedStates = (boundedStates - term + MOD) % MOD;
            } else {
                boundedStates = (boundedStates + term) % MOD;
            }
        }

        maxAtLeastR = (totalStates - boundedStates + MOD) % MOD;
    }

    int64 validStates = C(s - r + p - 1, p - 1);
    int64 denominator = validStates * p % MOD;
    int64 answer = maxAtLeastR * modPow(denominator, MOD - 2) % MOD;

    cout << answer << '\n';
    return 0;
}

